	hint = [=[Hable con el agente del Círculo junto a las tumbas del Sosiego del Valor.]=],
	allegiance = "Círculo Cenarion",
	aliases = { "Layo" },
	sections = {
		{
			title = "Resumen",
			text = [=[Layo Starstrike es uno de los agentes del {link:cenarion-circle}Círculo Cenarion{/link} en {link:silithus}Silithus{/link}, y responde ante {link:rabine-saturna}Rabine Saturna{/link} en el {link:moonglade}Claro de la Luna{/link}. No vivía cuando se libró aquí la gran guerra. Aun así, siente que el pasado sigue vivo en el desierto, y procura no despertarlo.]=],
		},
		{
			title = "Importancia",
			text = [=[El trabajo de Layo en la {link:southwind-village}Aldea del Viento del Sur{/link} dio al Círculo su primera ventana al pasado de la antigua guerra.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Vigila el desierto desde el cementerio del {link:valor-s-rest}Sosiego del Valor{/link}.
• Envió el primer hallazgo del Círculo en el {link:southwind-village}Viento del Sur{/link} al archivero {link:umber}Umber{/link}, en el {link:moonglade}Claro de la Luna{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La colmena de la torre",
			hint = [=[Libere a los espíritus de la Aldea del Viento del Sur y agite la colmena de su torre.]=],
			text = [=[Los espíritus del {link:southwind-village}Viento del Sur{/link} gimen, y la colmena de la torre de la aldea les responde. Cuando la agitaron, entregó algo extraño: un bulto de quitina silítida con forma de caja, por el que asomaba la esquina de un libro antiguo. Layo esperaba que fuera un diario de los tiempos antiguos, conservado en su caparazón.]=],
		},
	},
	mentions = {
		{ text = "Wasteland" },
		{ text = "The Spirits of Southwind" },
		{ text = "Hive in the Tower" },
		{ text = "{link:umber}Umber{/link}, Archivist" },
	},
	bonds = {
		{ id = "rabine-saturna", name = "Rabine Saturna", note = "su superior en el Claro de la Luna" },
		{ id = "umber", name = "Umber", note = "lee lo que él encuentra" },
	},
})

Translate("esES", "ralo-shan-the-eternal-watcher", {
	title = "Ralo'shan el Vigía Eterno",
	subtitle = "El Vigía Eterno",
	found = "El desierto al este del Fuerte Cenarion",
	hint = "Busque al vigía que está solo en el desierto oriental.",
	allegiance = "Círculo Cenarion",
	aliases = { "Ralo'shan" },
	sections = {
		{
			title = "Resumen",
			text = [=[Ralo'shan está solo en el desierto, al este del {link:cenarion-hold}Fuerte Cenarion{/link}. Dice que fue aquí donde los qiraji comenzaron su marcha a través de {link:kalimdor}Kalimdor{/link}, hace casi mil años. Es uno de los pocos que quedan de aquellos días, ligado a la vez al pasado y al presente. No sabe por qué debe quedarse. Solo sabe que debe hacerlo.]=],
		},
		{
			title = "Importancia",
			text = [=[A Ralo'shan lo han matado cien veces, y cada vez vuelve a despertar donde está. Algunos lo llaman maldito. Otros lo llaman heraldo de una nueva era.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Mantiene su guardia donde comenzó la invasión qiraji.
• Advierte que fuerzas antiguas se agitan, y que las pesadillas han empezado a salir del {link:emerald-dream}Sueño Esmeralda{/link}.]=],
		},
	},
	bonds = {
		{ id = "baristolth-of-the-shifting-sands", name = "Baristolth of the Shifting Sands", note = "otro que permanece desde la antigua guerra" },
	},
})

Translate("esES", "highlord-demitrian", {
	title = "Alto señor Demitrian",
	subtitle = "Servidor del Príncipe del Aire",
	found = "La Vega de Cristal, junto a un campo arrasado",
	hint = [=[Busque al alto señor que espera en el rincón noroeste del desierto.]=],
	allegiance = "Príncipe Thunderaan",
	aliases = { "Demitrian" },
	sections = {
		{
			title = "Resumen",
			text = [=[El alto señor Demitrian espera en el noroeste de {link:silithus}Silithus{/link}, junto a un campo arrasado. Enseña que los {red:old-gods}Dioses Antiguos{/red} hicieron el mundo y fueron derribados por los titanes, a quienes llama usurpadores. Sirve a Thunderaan, Príncipe del Aire. En las guerras de los elementos, dice, los lugartenientes del Señor del Fuego, {red:ragnaros}Ragnaros{/red}, traicionaron a Thunderaan, y Ragnaros lo abatió y se alimentó de su esencia. Lo poco que quedó fue atado en un talismán, y el talismán se partió en dos.]=],
		},
		{
			title = "Importancia",
			text = [=[Demitrian guarda un recuerdo de las antiguas guerras de los elementos que pocos mortales han oído. No tolera que se pronuncie ante él el nombre del Señor del Fuego.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Enseña la historia de los Dioses Antiguos y de las guerras elementales a quienes quieran escuchar.
• Espera a alguien que pueda restaurar al Príncipe del Aire.]=],
		},
	},
	mentions = {
		{ text = "Thunderaan the Windseeker" },
	},
})

Translate("esES", "aendel-windspear", {
	title = "Aendel Windspear",
	subtitle = "Un fantasma del Viento del Sur",
	found = "Las ruinas de la Aldea del Viento del Sur",
	hint = [=[Busque al fantasma silencioso entre las ruinas de la Aldea del Viento del Sur.]=],
	allegiance = "Círculo Cenarion",
	aliases = { "Aendel" },
	sections = {
		{
			title = "Resumen",
			text = [=[Entre las ruinas de la {link:southwind-village}Aldea del Viento del Sur{/link} se alza el fantasma de una mujer. Mira a los vivos con desconfianza y no habla. Aun así, comercia. A quienes se han ganado la confianza del {link:cenarion-circle}Círculo Cenarion{/link} les ofrece patrones de armadura de cuero, algunos con nombres de los silítidos de las colmenas y de las criaturas del desierto.]=],
		},
		{
			title = "Importancia",
			text = [=[De todos los muertos del {link:southwind-village}Viento del Sur{/link}, solo Aendel trata con los vivos.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ningún registro cuenta quién fue Aendel en vida, ni cómo llegó a quedarse en las ruinas.]=],
		},
	},
})
